<div class="admin-page-heading"><div><span class="admin-eyebrow">CUSTOMER RELATIONSHIPS</span><p>Review project requests and track each enquiry through your follow-up process.</p></div></div><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>REFERENCE</th><th>CLIENT</th><th>CONTACT</th><th>SERVICE</th><th>STATUS</th><th>DATE</th><th></th></tr></thead><tbody><?php foreach($enquiries as $enquiry): ?><tr><td><strong><?= e($enquiry['reference_code']) ?></strong></td><td><?= e($enquiry['full_name']) ?></td><td><a href="tel:<?= e($enquiry['phone']) ?>"><?= e($enquiry['phone']) ?></a><small><?= e($enquiry['email']??'') ?></small></td><td><?= e($enquiry['service_type']?:'—') ?></td><td><span class="status status-<?= e($enquiry['status']) ?>"><?= e(str_replace('_',' ',$enquiry['status'])) ?></span></td><td><?= e(format_date($enquiry['created_at'])) ?></td><td><a class="table-action" href="<?= e(url('/admin/enquiries/'.$enquiry['id'])) ?>">Open ↗</a></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$enquiries): ?><div class="admin-empty"><span>◷</span><h3>No enquiries yet</h3><p>Project enquiries will appear here after visitors submit the quote form.</p></div><?php endif; ?></section>
